  ui_story_5027_50270101_23_dialog_content = "No he visto poderes como los tuyos antes.\nPensar que los bandidos poseerían este tipo de fuerza... Ahora realmente no puedo dejarte ir. ¡Grilletes! ¡Desbloquear!",
