  ui_story_5027_50270101_42_dialog_content = "Reina, Guasón, entendemos que no sois nuestros enemigos.\nPero lo siento, no tenemos tiempo para ayudarte en este momento... Tenemos que volver a nuestra misión.\nTenemos que irnos, PlayerName!",
