  ui_story_5027_50270101_49_dialog_content = "Después de mucha investigación, finalmente localizamos su base de operaciones.\nLos Mercenarios de la Llama Blanca iban a lanzar un ataque sorpresa esta noche.",
  ui_story_5027_50270101_50_dialog_content = "Sin embargo, nos encontramos con algunos problemas...",
  ui_story_5027_50270101_51_dialog_content = "¿Problemas?",
