  ui_story_5027_50270101_66_dialog_content = "No puedo quedarme quieto, ¿eh?",
  ui_story_5027_50270101_67_dialog_content = "Suena como palabras directamente de la boca de cierta persona, ¿verdad?",
  ui_story_5027_50270101_68_dialog_content = "Joker, Reina, como Comandante Adjunto de los Mercenarios de la Llama Blanca...\nMe gustaría contar con su ayuda para acabar con los bandidos.",
