  ui_story_5027_50270101_71_dialog_content = "Sí. Ahora, PlayerName, Luke, ¿por qué no nos llevas a la base de bandidos?",
  ui_story_5027_50270101_72_dialog_content = "Así que aquí es donde los bandidos se han estado escondiendo... Qué artístico.\nApuesto a que Fox querría dibujarlo si estuviera aquí.",
  ui_story_5027_50270101_73_dialog_content = "La presencia de esas cosas es aún más prominente aquí.\nSin embargo, lo que no entiendo es por qué también siento un aura de tristeza entremezclada con la maldad de los bandidos.",
