  ui_story_5027_50270201_9_dialog_content = "Joker es casi tan ágil como Violet.",
  ui_story_5027_50270201_10_dialog_content = "Ahí. La puerta está desbloqueada. Entremos.",
  ui_story_5027_50270201_11_dialog_content = "No hay mucho aquí para una sala del tesoro.",
