  ui_story_5027_50270201_17_dialog_content = "Parece que no ha sido tratado humanamente.",
  ui_story_5027_50270201_18_dialog_content = "Tiene moretones por todo el cuerpo.",
  ui_story_5027_50270201_19_dialog_content = "Eso es exactamente lo que sentí justo afuera de la base de bandidos.\nNo pensé que un niño pudiera llevar una desesperación tan pesada...",
  ui_story_5027_50270201_20_dialog_content = "¿Quienes son ustedes?",
