  ui_story_5027_50270201_44_dialog_content = "¡Os hemos encontrado, intrusos!",
  ui_story_5027_50270201_45_dialog_content = "¡Maldita sea, son rápidos! ¡Date prisa, persíguelos hasta la habitación del jefe!",
