  ui_story_5027_50270201_64_dialog_content = "¡Es una trampa!",
  ui_story_5027_50270201_65_dialog_content = "¡Es demasiado tarde!",
  ui_story_5027_50270201_66_dialog_content = "¡Barr, corre!",
  ui_story_5027_50270201_67_dialog_content = "¡Ahhh!",
  ui_story_5027_50270201_68_dialog_content = "Ustedes...!",
  ui_story_5027_50270201_69_dialog_content = "Oh, ¿me perdí uno? Bueno, eso no es nada de qué preocuparse.",
  ui_story_5027_50270201_70_dialog_content = "¿Qué puede hacer un enano sin valor?\nJa, ¿qué pasa con esa mirada en tu cara, Barr?\n¿Quieres intentar quitarme esta llave?",
