  ui_story_5027_50270201_76_dialog_content = "Yo...",
  ui_story_5027_50270201_77_dialog_content = "Quieres libertad, ¿no?",
  ui_story_5027_50270201_78_dialog_content = "Libertad...",
  ui_story_5027_50270201_79_dialog_content = "Oh, qué emotivo, estoy a punto de derramar lágrimas aquí.\n¡Voy a masacrar a ese niño y disfrutaré el sonido de todos tus llantos!\n¡Jajajaja!",
  ui_story_5027_50270201_80_dialog_content = "*Sollozo*",
  ui_story_5027_50270201_81_dialog_content = "Siempre iba a matarte tarde o temprano...\nBien podría ser hoy. Barr, saluda a tus padres de mi parte, ¿quieres?",
