  ui_story_5027_50270201_86_dialog_content = "Al menos, es hora de jugar.",
  ui_story_5027_50270201_87_dialog_content = "Gracias, Barr.",
  ui_story_5027_50270201_88_dialog_content = "¡Ahora las tornas han cambiado!",
  ui_story_5027_50270201_89_dialog_content = "¡Rayos!",
  ui_story_5027_50270201_90_dialog_content = "Ahora, jaque mate.",
  ui_story_5027_50270201_91_dialog_content = "Yo... no he probado el aire exterior en tanto tiempo...",
  ui_story_5027_50270201_92_dialog_content = "Le he enviado un mensaje a mi gente para que se ocupe de las cosas aquí. No te preocupes, este es el final de los bandidos.",
