  ui_story_5027_50270201_94_dialog_content = "Gracias... ¡Gracias a todos por salvarme!",
  ui_story_5027_50270201_95_dialog_content = "Entonces, Joker, ¿cómo lo convenciste?",
  ui_story_5027_50270201_96_dialog_content = "Sí, me he estado preguntando qué le dio la fuerza para enfrentarse a Rucker.",
  ui_story_5027_50270201_97_dialog_content = "Es como una persona completamente diferente a la que conocimos por primera vez.",
  ui_story_5027_50270201_98_dialog_content = "no hice nada Barr decidió por sí mismo que era hora de enfrentarse a Rucker.",
  ui_story_5027_50270201_99_dialog_content = "Oye, échale un vistazo... ¡La luna está hermosa esta noche!",
  ui_story_5027_50270201_100_dialog_content = "De verdad...",
  ui_story_5027_50270201_101_dialog_content = "La vista realmente levanta el ánimo, ¿no es así?",
  ui_story_5027_50270201_102_dialog_content = "Yo... En realidad... Un pensamiento vino a mí cuando vi que todos ustedes estaban siendo capturados.",
  ui_story_5027_50270201_103_dialog_content = "He leído cómics antes sobre ladrones que ayudan a los débiles. Luchan por lo que creen.\nAsí que... pensé, tal vez yo también podría hacer eso, ¡luchar por la libertad de todos!",
  ui_story_5027_50270201_104_dialog_content = "Así fue como encontré fuerza en mí mismo, creo... Y tú, dijiste...",
  ui_story_5027_50270201_105_dialog_content = "El Guasón y la Reina se han ido...",
  ui_story_5027_50270201_106_dialog_content = "¿A dónde fueron?",
  ui_story_5027_50270201_107_dialog_content = "Hay luna llena esta noche, Barr. Tu deseo se hizo realidad.",
